Here is a simple script in Python to close all running applications on Windows:

```python
import win32api, win32con

def get_all_windows():
    processes = win32api.GetAllProcesses()
    windows = []
    for process in processes:
        try:
            window = win32gui.FindWindowEx(None, 0, process['ImageName'], None)
            if window != 0:
                windows.append((process, window))
        except Exception as e:
            print(f"Error getting window for {process['ImageName']}: {e}")
    return windows

def close_window(window):
    win32gui.SetForegroundWindow(window[1])
    win32api.SendMessage(window[1], win32con.WM_CLOSE, 0, 0)

def close_all():
    windows = get_all_windows()
    for window in windows:
        close_window(window)

close_all()
```

This script uses the `win32api` and `win
